select to_regprocedure('public.admin_member_list(text,text,integer,integer,text,text,date,date,uuid)') is not null as member_sort, to_regprocedure('public.admin_lesson_detail(uuid)') is not null as lesson_detail, to_regprocedure('public.admin_lesson_change(uuid,timestamptz,text,jsonb,text)') is not null as lesson_change, exists(select 1 from pg_trigger where tgrelid='public.teacher_lessons'::regclass and tgname='lesson_revision_submission' and tgenabled='O') as revision_trigger, to_regprocedure('public.public_lesson_catalog(jsonb,uuid)') is not null as catalog, to_regprocedure('public.lesson_booking_slots(uuid,date)') is not null as slots;